--
-- Name: advance_spec_scope_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advance_spec_scope_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.scope_revision := OLD.scope_revision;
    IF spec_scope_contract(OLD.intent, OLD.shape_output, OLD.specify_output)
        IS DISTINCT FROM spec_scope_contract(NEW.intent, NEW.shape_output, NEW.specify_output) THEN
        NEW.scope_revision := OLD.scope_revision + 1;
    END IF;
    RETURN NEW;
END;
$$;


