CREATE FUNCTION public.record_dependency_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF ROW(OLD.project_slug, OLD.from_slug, OLD.to_slug, OLD.edge_type)
            IS NOT DISTINCT FROM ROW(NEW.project_slug, NEW.from_slug, NEW.to_slug, NEW.edge_type) THEN
            RETURN NULL;
        END IF;
    END IF;

    IF TG_OP IN ('DELETE', 'UPDATE') THEN
        IF OLD.edge_type IN ('DEPENDS_ON', 'BLOCKS') THEN
            INSERT INTO dependency_changes (project_slug, dependent_slug, prerequisite_slug, edge_type, operation)
            VALUES (OLD.project_slug,
                CASE WHEN OLD.edge_type = 'DEPENDS_ON' THEN OLD.from_slug ELSE OLD.to_slug END,
                CASE WHEN OLD.edge_type = 'DEPENDS_ON' THEN OLD.to_slug ELSE OLD.from_slug END,
                OLD.edge_type, 'DELETE');
        END IF;
    END IF;

    IF TG_OP IN ('INSERT', 'UPDATE') THEN
        IF NEW.edge_type IN ('DEPENDS_ON', 'BLOCKS') THEN
            INSERT INTO dependency_changes (project_slug, dependent_slug, prerequisite_slug, edge_type, operation)
            VALUES (NEW.project_slug,
                CASE WHEN NEW.edge_type = 'DEPENDS_ON' THEN NEW.from_slug ELSE NEW.to_slug END,
                CASE WHEN NEW.edge_type = 'DEPENDS_ON' THEN NEW.to_slug ELSE NEW.from_slug END,
                NEW.edge_type, 'INSERT');
        END IF;
    END IF;
    RETURN NULL;
END;
$$;


