CREATE FUNCTION public.spec_scope_contract(intent text, shape jsonb, specify jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT jsonb_build_object(
        'intent', intent,
        'shape', COALESCE((SELECT jsonb_object_agg(key, value)
