CREATE TABLE public.node_ownership_operations (
    id text PRIMARY KEY,
    project_slug text NOT NULL,
    task_slug text NOT NULL,
    idempotency_key text NOT NULL,
    action text NOT NULL CHECK (action IN ('take','return')),
    status text NOT NULL CHECK (status IN ('pending','committed','cancelled')),
    before_owner_user_id text,
    after_owner_user_id text,
    from_version integer NOT NULL,
    to_version integer,
    actor_user_id text NOT NULL,
    reason text NOT NULL,
    dispatches jsonb NOT NULL DEFAULT '[]'::jsonb,
    preparations jsonb NOT NULL DEFAULT '[]'::jsonb,
    handoffs jsonb NOT NULL DEFAULT '[]'::jsonb,
    prepared_handoffs jsonb NOT NULL DEFAULT '[]'::jsonb,
    frozen_claim jsonb,
    claim_handoff jsonb,
    created_at timestamptz NOT NULL,
    finished_at timestamptz,
    cancel_actor_user_id text,
    cancel_reason text,
    UNIQUE(project_slug,idempotency_key),
    CHECK (jsonb_typeof(dispatches)='array' AND jsonb_typeof(preparations)='array' AND jsonb_typeof(handoffs)='array' AND jsonb_typeof(prepared_handoffs)='array'
        AND (frozen_claim IS NULL OR jsonb_typeof(frozen_claim)='object') AND (claim_handoff IS NULL OR jsonb_typeof(claim_handoff)='object')),
    CHECK ((status='pending' AND finished_at IS NULL AND to_version IS NULL AND cancel_actor_user_id IS NULL AND cancel_reason IS NULL)
        OR (status='committed' AND finished_at IS NOT NULL AND to_version IS NOT NULL AND cancel_actor_user_id IS NULL AND cancel_reason IS NULL)
        OR (status='cancelled' AND finished_at IS NOT NULL AND to_version IS NULL AND cancel_actor_user_id IS NOT NULL AND cancel_reason IS NOT NULL))
);
