--
-- Node judgment revisions are append-only through their storage owner.
-- Current state is the latest revision, including explicit clearance.
--

CREATE TABLE public.node_marks (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    project_slug text NOT NULL REFERENCES public.projects(slug),
    task_slug text NOT NULL,
    kind text NOT NULL,
    value text NOT NULL,
    reason text NOT NULL CHECK (char_length(reason) BETWEEN 1 AND 4000 AND btrim(reason) <> ''),
    actor text NOT NULL CHECK (btrim(actor) <> ''),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    FOREIGN KEY (project_slug, task_slug) REFERENCES public.specs(project_slug, slug),
    CHECK ((kind = 'risk' AND value IN ('watch', 'high', 'cleared'))
        OR (kind = 'critical' AND value IN ('marked', 'cleared')))
);

CREATE INDEX node_marks_task_history ON public.node_marks (project_slug, task_slug, id DESC);

CREATE TABLE public.node_execution_events (
    id text NOT NULL CHECK (id ~ '^[A-Za-z0-9_-]{1,128}$'),
    event_order bigint GENERATED ALWAYS AS IDENTITY UNIQUE,
    project_slug text NOT NULL REFERENCES public.projects(slug),
    task_slug text NOT NULL,
    kind text NOT NULL CHECK (kind IN ('retry','rework','git_undo')),
    reason text NOT NULL CHECK (btrim(reason)<>'' AND char_length(reason)<=4000),
    actor text NOT NULL CHECK (btrim(actor)<>''),
    previous_run_id text,
    run_id text,
    delivery_id text REFERENCES public.deliveries(id),
    git_undo jsonb,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    PRIMARY KEY (project_slug,id),
    FOREIGN KEY (project_slug,task_slug) REFERENCES public.specs(project_slug,slug),
    FOREIGN KEY (project_slug,previous_run_id) REFERENCES public.run_bindings(project_slug,id),
    FOREIGN KEY (project_slug,run_id) REFERENCES public.run_bindings(project_slug,id),
    CHECK ((kind='retry' AND previous_run_id IS NOT NULL AND delivery_id IS NULL AND git_undo IS NULL)
        OR (kind='rework' AND delivery_id IS NOT NULL AND previous_run_id IS NULL AND run_id IS NULL AND git_undo IS NULL)
        OR (kind='git_undo' AND previous_run_id IS NULL AND delivery_id IS NULL AND run_id IS NOT NULL
            AND git_undo IS NOT NULL AND jsonb_typeof(git_undo)='object'
            AND git_undo ? 'operation' AND git_undo ? 'sourceCommit' AND git_undo ? 'resultCommit'
            AND jsonb_typeof(git_undo->'operation')='string'
            AND jsonb_typeof(git_undo->'sourceCommit')='string'
            AND jsonb_typeof(git_undo->'resultCommit')='string'
            AND git_undo->>'operation' IN ('revert','reset')
            AND git_undo->>'sourceCommit' ~ '^([0-9a-fA-F]{40}|[0-9a-fA-F]{64})$'
            AND git_undo->>'resultCommit' ~ '^([0-9a-fA-F]{40}|[0-9a-fA-F]{64})$'
            AND (git_undo->>'operation'<>'revert' OR lower(git_undo->>'sourceCommit')<>lower(git_undo->>'resultCommit'))))
);
CREATE INDEX node_execution_events_history ON public.node_execution_events(project_slug,task_slug,event_order DESC);

CREATE TABLE public.review_requests (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    project_slug text NOT NULL REFERENCES public.projects(slug),
    task_slug text NOT NULL,
    kind text NOT NULL CHECK (kind IN ('requirements','design')),
    sources jsonb NOT NULL CHECK (jsonb_typeof(sources)='array' AND jsonb_array_length(sources)>0),
    author_responsibility jsonb NOT NULL CHECK (jsonb_typeof(author_responsibility)='object'),
    requirement_decision_ids jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(requirement_decision_ids)='array'),
    reviewer_run_id text NOT NULL REFERENCES public.run_bindings(id),
    completion_run_id text,
    responsible_user_id text NOT NULL,
    max_review_rounds integer NOT NULL CHECK (max_review_rounds > 0),
    agent_rejections integer DEFAULT 0 NOT NULL CHECK (agent_rejections >= 0),
    human_hold boolean DEFAULT false NOT NULL,
    created_by text NOT NULL,
    assigned_by_run_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_at timestamp with time zone,
    FOREIGN KEY (project_slug, task_slug) REFERENCES public.specs(project_slug, slug),
    FOREIGN KEY (project_slug, completion_run_id) REFERENCES public.run_bindings(project_slug,id),
    UNIQUE (project_slug,id)
);

CREATE INDEX review_requests_task ON public.review_requests(project_slug,task_slug,kind,id DESC);

CREATE TABLE public.review_decisions (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    project_slug text NOT NULL,
    request_id bigint NOT NULL,
    verdict text NOT NULL CHECK (verdict IN ('accepted','rejected')),
    basis text NOT NULL CHECK (btrim(basis)<>'' AND char_length(basis)<=4000),
    actor_kind text NOT NULL CHECK (actor_kind IN ('human','agent')),
    actor text NOT NULL,
    reviewer_run_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    FOREIGN KEY (project_slug,request_id) REFERENCES public.review_requests(project_slug,id),
    CHECK ((actor_kind='agent' AND reviewer_run_id IS NOT NULL) OR (actor_kind='human' AND reviewer_run_id IS NULL))
);
CREATE INDEX review_decisions_request ON public.review_decisions(project_slug,request_id,id);
CREATE UNIQUE INDEX review_decisions_agent_request ON public.review_decisions(project_slug,request_id) WHERE actor_kind='agent';

ALTER TABLE public.acceptances
    ADD COLUMN actor_kind text NOT NULL DEFAULT '' CHECK (actor_kind IN ('','human','agent')),
    ADD COLUMN reviewer_run_id text,
    ADD COLUMN review_request_id bigint;

CREATE UNIQUE INDEX acceptances_agent_request ON public.acceptances(project_slug,review_request_id) WHERE actor_kind='agent';

CREATE TABLE public.mail_owner_events (
    project_slug text NOT NULL,
    id text NOT NULL,
    thread_id text NOT NULL,
    from_run text NOT NULL,
    to_run text NOT NULL,
    actor_kind text NOT NULL CHECK (actor_kind IN ('human','agent')),
    actor_user_id text NOT NULL CHECK (btrim(actor_user_id)<>''),
    actor_run_id text,
    reason text NOT NULL CHECK (btrim(reason)<>'' AND octet_length(reason)<=65536),
    idempotency_key text NOT NULL CHECK (btrim(idempotency_key)<>'' AND octet_length(idempotency_key)<=256),
    created_at timestamp with time zone NOT NULL,
    PRIMARY KEY (project_slug,id),
    UNIQUE NULLS NOT DISTINCT (project_slug,actor_user_id,actor_run_id,idempotency_key),
    FOREIGN KEY (project_slug,thread_id) REFERENCES public.mail_threads(project_slug,id),
    FOREIGN KEY (project_slug,from_run) REFERENCES public.run_bindings(project_slug,id),
    FOREIGN KEY (project_slug,to_run) REFERENCES public.run_bindings(project_slug,id),
    FOREIGN KEY (project_slug,actor_run_id) REFERENCES public.run_bindings(project_slug,id),
    CHECK (from_run<>to_run),
    CHECK ((actor_kind='human' AND actor_run_id IS NULL) OR (actor_kind='agent' AND actor_run_id IS NOT NULL))
);
CREATE INDEX mail_owner_events_thread ON public.mail_owner_events(project_slug,thread_id,id DESC);

CREATE TABLE public.delivery_test_hooks (
    project_slug text NOT NULL REFERENCES public.projects(slug),
    id text NOT NULL,
    hook_kind text NOT NULL DEFAULT 'delivery_test' CHECK (hook_kind IN ('delivery_test','completion_program')),
    source_run_id text,
    source_task_slug text,
    source_spec_id text,
    source_role text CHECK (source_role IN ('work','summary')),
    requested_fact_kind text CHECK (requested_fact_kind IN ('execution','manual','summary')),
    requested_fact_id text,
    fact_kind text CHECK (fact_kind IN ('execution','manual','summary')),
    fact_id text,
    program_admission_id text REFERENCES public.run_dispatches(id),
    target_run_id text NOT NULL,
    target_package_id text NOT NULL REFERENCES public.context_packages(id),
    commit_sha text CHECK (commit_sha ~ '^([0-9a-fA-F]{40}|[0-9a-fA-F]{64})$'),
    configured_by_run_id text,
    configured_by_user_id text NOT NULL CHECK (btrim(configured_by_user_id)<>''),
    host_consumer_user_id text NOT NULL CHECK (btrim(host_consumer_user_id)<>''),
    idempotency_key text NOT NULL,
    requested_delivery_id text REFERENCES public.deliveries(id),
    delivery_id text REFERENCES public.deliveries(id),
    created_at timestamp with time zone NOT NULL,
    triggered_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    cancelled_by_run_id text,
    cancelled_by_user_id text,
    cancellation_reason text,
    dispatch_status text CHECK (dispatch_status IN ('commandAccepted','rejected','unconfirmed','blocked')),
    dispatch_phase text CHECK (dispatch_phase IN ('create','start')),
    dispatch_detail text,
    dispatch_recorded_at timestamp with time zone,
    retried_at timestamp with time zone,
    retried_by_run_id text,
    retried_by_user_id text,
    PRIMARY KEY (project_slug,id),
    UNIQUE (project_slug,configured_by_run_id,idempotency_key),
    FOREIGN KEY (project_slug,source_task_slug) REFERENCES public.specs(project_slug,slug),
    FOREIGN KEY (project_slug,source_run_id) REFERENCES public.run_bindings(project_slug,id),
    FOREIGN KEY (project_slug,target_run_id) REFERENCES public.run_bindings(project_slug,id),
    FOREIGN KEY (project_slug,configured_by_run_id) REFERENCES public.run_bindings(project_slug,id),
    FOREIGN KEY (project_slug,cancelled_by_run_id) REFERENCES public.run_bindings(project_slug,id),
    FOREIGN KEY (project_slug,retried_by_run_id) REFERENCES public.run_bindings(project_slug,id),
    CHECK (source_run_id<>target_run_id),
    CHECK ((hook_kind='delivery_test' AND source_run_id IS NOT NULL AND commit_sha IS NOT NULL
        AND source_task_slug IS NULL AND source_spec_id IS NULL AND source_role IS NULL
        AND requested_fact_kind IS NULL AND requested_fact_id IS NULL AND fact_kind IS NULL AND fact_id IS NULL AND program_admission_id IS NULL
        AND ((delivery_id IS NULL)=(triggered_at IS NULL))) OR
        (hook_kind='completion_program' AND source_run_id IS NULL AND commit_sha IS NULL
        AND source_task_slug IS NOT NULL AND source_spec_id IS NOT NULL AND source_role IS NOT NULL
        AND configured_by_run_id IS NULL AND requested_delivery_id IS NULL AND delivery_id IS NULL
        AND ((fact_id IS NULL)=(triggered_at IS NULL)) AND ((fact_id IS NULL)=(fact_kind IS NULL))
        AND ((requested_fact_id IS NULL)=(requested_fact_kind IS NULL))
        AND (requested_fact_id IS NULL OR (fact_id IS NOT NULL AND requested_fact_id=fact_id AND requested_fact_kind=fact_kind))
        AND (program_admission_id IS NULL OR fact_id IS NOT NULL)
        AND (fact_kind IS NULL OR (source_role='summary' AND fact_kind='summary') OR (source_role='work' AND fact_kind IN ('execution','manual')))
        AND (dispatch_status IS NULL OR dispatch_status IN ('blocked','unconfirmed')) AND dispatch_phase IS NULL)),
    CHECK ((dispatch_status IS NULL AND dispatch_phase IS NULL AND dispatch_detail IS NULL AND dispatch_recorded_at IS NULL)
        OR (dispatch_status IS NOT NULL AND dispatch_recorded_at IS NOT NULL AND (delivery_id IS NOT NULL OR fact_id IS NOT NULL)
            AND (dispatch_detail IS NULL OR char_length(dispatch_detail)<=4000))),
    CHECK (dispatch_status IS NULL OR dispatch_status IN ('blocked','unconfirmed')
        OR (dispatch_status='commandAccepted' AND dispatch_phase IS NOT NULL AND dispatch_phase='start')
        OR (dispatch_status='rejected' AND dispatch_phase IS NOT NULL)),
    CHECK (requested_delivery_id IS NULL OR (delivery_id IS NOT NULL AND requested_delivery_id=delivery_id)),
    CHECK ((cancelled_at IS NULL AND cancelled_by_run_id IS NULL AND cancelled_by_user_id IS NULL AND cancellation_reason IS NULL)
        OR (cancelled_at IS NOT NULL AND cancelled_by_user_id IS NOT NULL
            AND cancellation_reason IS NOT NULL AND btrim(cancellation_reason)<>'' AND char_length(cancellation_reason)<=4000)),
    CHECK ((retried_at IS NULL AND retried_by_run_id IS NULL AND retried_by_user_id IS NULL)
        OR (retried_at IS NOT NULL AND retried_by_user_id IS NOT NULL))
);
CREATE UNIQUE INDEX delivery_test_hooks_human_key ON public.delivery_test_hooks(project_slug,configured_by_user_id,idempotency_key)
    WHERE configured_by_run_id IS NULL;
CREATE INDEX delivery_test_hooks_source ON public.delivery_test_hooks(project_slug,source_run_id,commit_sha)
    WHERE hook_kind='delivery_test' AND delivery_id IS NULL AND cancelled_at IS NULL;
CREATE UNIQUE INDEX delivery_test_hooks_delivery_target ON public.delivery_test_hooks(project_slug,target_run_id)
    WHERE hook_kind='delivery_test';
CREATE UNIQUE INDEX delivery_test_hooks_completion_target ON public.delivery_test_hooks(project_slug,target_run_id)
    WHERE hook_kind='completion_program' AND cancelled_at IS NULL;
CREATE INDEX delivery_test_hooks_completion_source ON public.delivery_test_hooks(project_slug,source_task_slug,source_spec_id)
    WHERE hook_kind='completion_program' AND fact_id IS NULL AND cancelled_at IS NULL;
ALTER TABLE public.execution_events ADD COLUMN completion_context jsonb;
ALTER TABLE public.execution_events ADD COLUMN program_completion_basis jsonb CHECK (program_completion_basis IS NULL OR jsonb_typeof(program_completion_basis)='object');
ALTER TABLE public.manual_completions ADD COLUMN completion_context jsonb;

ALTER TABLE public.specs ADD COLUMN completion_generation bigint NOT NULL DEFAULT 0;
CREATE FUNCTION public.advance_completion_generation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW.completion_generation := OLD.completion_generation;
    IF NEW.stage IS DISTINCT FROM OLD.stage THEN
        NEW.completion_generation := OLD.completion_generation + 1;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER advance_completion_generation BEFORE UPDATE ON public.specs
    FOR EACH ROW EXECUTE FUNCTION public.advance_completion_generation();

CREATE TABLE public.summary_obligations (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
