    project_slug text NOT NULL REFERENCES public.projects(slug),
    from_slug text NOT NULL,
    to_slug text NOT NULL,
    edge_type text NOT NULL CHECK (edge_type IN ('COMPOSES','DECIDED_IN')),
    operation text NOT NULL CHECK (operation IN ('INSERT','DELETE')),
    dispositions jsonb NOT NULL DEFAULT '[]'::jsonb,
    lost_obligations jsonb NOT NULL DEFAULT '[]'::jsonb,
    actor_user_id text,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX composition_changes_project ON public.composition_changes(project_slug,id);
CREATE INDEX composition_changes_pair ON public.composition_changes(project_slug,from_slug,to_slug,edge_type,id DESC);

CREATE TABLE public.report_branch_flows (
    id text PRIMARY KEY,
    project_slug text NOT NULL REFERENCES public.projects(slug),
    configured_by text NOT NULL,
    idempotency_key text NOT NULL,
    definition jsonb NOT NULL,
    created_at timestamptz NOT NULL,
    cancelled_by text,
    cancel_reason text,
    cancelled_at timestamptz,
    UNIQUE (project_slug,id),
    UNIQUE (project_slug,configured_by,idempotency_key),
    CHECK ((cancelled_by IS NULL AND cancel_reason IS NULL AND cancelled_at IS NULL)
        OR (cancelled_by IS NOT NULL AND cancel_reason IS NOT NULL AND cancelled_at IS NOT NULL))
);

CREATE TABLE public.report_branch_members (
    project_slug text NOT NULL,
    flow_id text NOT NULL,
    run_id text NOT NULL,
    package_id text NOT NULL,
    condition_key text NOT NULL,
    when_value text NOT NULL CHECK (when_value IN ('true','false')),
    PRIMARY KEY (project_slug,run_id),
    FOREIGN KEY (project_slug,flow_id) REFERENCES public.report_branch_flows(project_slug,id),
    FOREIGN KEY (project_slug,run_id) REFERENCES public.run_bindings(project_slug,id),
    FOREIGN KEY (package_id) REFERENCES public.context_packages(id)
);
CREATE INDEX report_branch_members_flow ON public.report_branch_members(project_slug,flow_id);

CREATE TABLE public.report_branch_judgments (
    id text PRIMARY KEY,
    record_order bigint GENERATED ALWAYS AS IDENTITY UNIQUE,
    project_slug text NOT NULL,
    flow_id text NOT NULL,
    condition_key text NOT NULL,
    value text NOT NULL CHECK (value IN ('true','false','unknown')),
    input_refs jsonb NOT NULL,
    reason text NOT NULL,
    actor_user_id text NOT NULL,
    actor_run_id text,
    recorded_at timestamptz NOT NULL,
    predecessor_id text,
    UNIQUE (project_slug,id),
    UNIQUE NULLS NOT DISTINCT (project_slug,flow_id,condition_key,predecessor_id),
    FOREIGN KEY (project_slug,flow_id) REFERENCES public.report_branch_flows(project_slug,id),
    FOREIGN KEY (project_slug,predecessor_id) REFERENCES public.report_branch_judgments(project_slug,id)
);
CREATE INDEX report_branch_judgments_latest ON public.report_branch_judgments(project_slug,flow_id,condition_key,record_order DESC);

CREATE TABLE public.report_flow_joins (
    project_slug text NOT NULL,
    flow_id text NOT NULL,
    run_id text NOT NULL,
    package_id text NOT NULL,
    mode text NOT NULL CHECK (mode IN ('all','any')),
    allow_empty_skip boolean NOT NULL,
    configured_by text NOT NULL,
    configured_at timestamptz NOT NULL,
    PRIMARY KEY (project_slug,run_id),
    FOREIGN KEY (project_slug,flow_id) REFERENCES public.report_branch_flows(project_slug,id),
    FOREIGN KEY (project_slug,run_id) REFERENCES public.run_bindings(project_slug,id),
    FOREIGN KEY (package_id) REFERENCES public.context_packages(id)
);
CREATE INDEX report_flow_joins_flow ON public.report_flow_joins(project_slug,flow_id);
ALTER TABLE public.run_dispatches ADD COLUMN report_flow_basis jsonb;
ALTER TABLE public.run_dispatches ADD COLUMN report_join_basis jsonb;

CREATE TABLE public.candidate_loops (
    project_slug text NOT NULL,
    run_id text NOT NULL,
    task_slug text NOT NULL,
    package_id text NOT NULL,
    max_attempts integer NOT NULL CHECK (max_attempts > 0),
    plan_sources jsonb NOT NULL,
    termination_kind text NOT NULL DEFAULT 'report' CHECK (termination_kind IN ('report','satisfaction')),
    satisfaction_criterion text,
    join_mode text CHECK (join_mode IN ('all','any')),
    join_allow_empty_skip boolean,
    configured_by text NOT NULL,
    configured_at timestamptz NOT NULL,
    stop_actor_user_id text,
    stop_actor_run_id text,
    stop_reason text,
    stopped_at timestamptz,
    abandon_actor_user_id text,
    abandon_reason text,
    abandoned_at timestamptz,
    resolved_at timestamptz,
    completed_join jsonb,
    completed_condition jsonb,
    completed_satisfaction jsonb,
    PRIMARY KEY (project_slug,run_id),
    FOREIGN KEY (project_slug,run_id) REFERENCES public.run_bindings(project_slug,id),
    FOREIGN KEY (project_slug,task_slug) REFERENCES public.specs(project_slug,slug),
    FOREIGN KEY (package_id) REFERENCES public.context_packages(id),
    CHECK ((stopped_at IS NULL AND stop_actor_user_id IS NULL AND stop_actor_run_id IS NULL AND stop_reason IS NULL)
        OR (stopped_at IS NOT NULL AND stop_actor_user_id IS NOT NULL AND stop_reason IS NOT NULL)),
    CHECK ((abandoned_at IS NULL AND abandon_actor_user_id IS NULL AND abandon_reason IS NULL)
        OR (abandoned_at IS NOT NULL AND abandon_actor_user_id IS NOT NULL AND abandon_reason IS NOT NULL)),
    CHECK ((join_mode IS NULL AND join_allow_empty_skip IS NULL)
        OR (join_mode IS NOT NULL AND join_allow_empty_skip IS NOT NULL)),
    CHECK ((termination_kind='report' AND satisfaction_criterion IS NULL)
        OR (termination_kind='satisfaction' AND satisfaction_criterion IS NOT NULL
            AND btrim(satisfaction_criterion)<>'' AND char_length(satisfaction_criterion)<=4000))
);
CREATE UNIQUE INDEX candidate_loops_unresolved_task ON public.candidate_loops(project_slug,task_slug)
 WHERE resolved_at IS NULL AND abandoned_at IS NULL;

CREATE TABLE public.candidate_attempts (
    project_slug text NOT NULL,
    id text NOT NULL,
    run_id text NOT NULL,
    ordinal integer NOT NULL CHECK (ordinal > 0),
    predecessor_id text,
    consumed_condition jsonb,
    consumed_join jsonb,
    consumed_satisfaction jsonb,
    granted_at timestamptz NOT NULL,
    delivery_id text,
    flow_id text,
    PRIMARY KEY (project_slug,id),
    UNIQUE (project_slug,run_id,ordinal),
    UNIQUE (project_slug,predecessor_id),
    UNIQUE (project_slug,delivery_id),
    UNIQUE (project_slug,flow_id),
    FOREIGN KEY (project_slug,run_id) REFERENCES public.candidate_loops(project_slug,run_id),
    FOREIGN KEY (project_slug,predecessor_id) REFERENCES public.candidate_attempts(project_slug,id),
    FOREIGN KEY (delivery_id) REFERENCES public.deliveries(id),
    FOREIGN KEY (project_slug,flow_id) REFERENCES public.report_branch_flows(project_slug,id)
);
CREATE INDEX candidate_attempts_run ON public.candidate_attempts(project_slug,run_id,ordinal DESC);

CREATE TABLE public.candidate_satisfaction_judgments (
    id text PRIMARY KEY,
    event_order bigint GENERATED ALWAYS AS IDENTITY UNIQUE,
    project_slug text NOT NULL,
    run_id text NOT NULL,
    attempt_id text NOT NULL,
    delivery_id text NOT NULL REFERENCES public.deliveries(id),
    predecessor_id text REFERENCES public.candidate_satisfaction_judgments(id),
    value text NOT NULL CHECK (value IN ('true','false','unknown')),
    reason text NOT NULL CHECK (btrim(reason)<>'' AND char_length(reason)<=4000),
    actor_user_id text NOT NULL,
    actor_run_id text,
    recorded_at timestamptz NOT NULL,
    UNIQUE NULLS NOT DISTINCT (project_slug,attempt_id,predecessor_id),
    FOREIGN KEY (project_slug,run_id) REFERENCES public.candidate_loops(project_slug,run_id),
    FOREIGN KEY (project_slug,attempt_id) REFERENCES public.candidate_attempts(project_slug,id)
);
CREATE INDEX candidate_satisfaction_judgments_history ON public.candidate_satisfaction_judgments(project_slug,attempt_id,event_order DESC);

CREATE TABLE public.candidate_interventions (
    id text PRIMARY KEY,
    event_order bigint GENERATED ALWAYS AS IDENTITY UNIQUE,
    project_slug text NOT NULL,
    run_id text NOT NULL,
    attempt_id text NOT NULL,
    judgment_id text NOT NULL REFERENCES public.candidate_satisfaction_judgments(id),
    report_ids jsonb NOT NULL,
    conflict_kind text NOT NULL CHECK (conflict_kind IN ('passed_false','failed_true')),
    reason text NOT NULL,
    recorded_at timestamptz NOT NULL,
    resolved_at timestamptz,
    resolved_by_user_id text,
    resolution_reason text,
    resolution_judgment_id text REFERENCES public.candidate_satisfaction_judgments(id),
    resolution_report_ids jsonb,
    FOREIGN KEY (project_slug,run_id) REFERENCES public.candidate_loops(project_slug,run_id),
    FOREIGN KEY (project_slug,attempt_id) REFERENCES public.candidate_attempts(project_slug,id),
    CHECK ((resolved_at IS NULL AND resolved_by_user_id IS NULL AND resolution_reason IS NULL
        AND resolution_judgment_id IS NULL AND resolution_report_ids IS NULL)
        OR (resolved_at IS NOT NULL AND resolved_by_user_id IS NOT NULL AND resolution_reason IS NOT NULL
            AND resolution_judgment_id IS NOT NULL AND resolution_report_ids IS NOT NULL))
);
CREATE UNIQUE INDEX candidate_interventions_active ON public.candidate_interventions(project_slug,attempt_id) WHERE resolved_at IS NULL;
CREATE INDEX candidate_interventions_history ON public.candidate_interventions(project_slug,attempt_id,event_order DESC);

CREATE TABLE public.node_merges (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    project_slug text NOT NULL REFERENCES public.projects(slug),
    actor_user_id text NOT NULL,
    actor_run_id text,
    idempotency_key text NOT NULL,
    request jsonb NOT NULL,
    receipt jsonb NOT NULL,
    target_slug text NOT NULL,
    created_at timestamptz NOT NULL,
    UNIQUE NULLS NOT DISTINCT (project_slug,actor_user_id,actor_run_id,idempotency_key),
    FOREIGN KEY (project_slug,target_slug) REFERENCES public.specs(project_slug,slug),
    FOREIGN KEY (project_slug,actor_run_id) REFERENCES public.run_bindings(project_slug,id)
);
CREATE TABLE public.node_merge_sources (
    project_slug text NOT NULL,
    merge_id bigint NOT NULL REFERENCES public.node_merges(id),
    source_slug text NOT NULL,
    source_id text NOT NULL,
    before_version integer NOT NULL,
    after_version integer NOT NULL,
    PRIMARY KEY (project_slug,merge_id,source_slug),
    FOREIGN KEY (project_slug,source_slug) REFERENCES public.specs(project_slug,slug)
);
CREATE INDEX node_merge_sources_history ON public.node_merge_sources(project_slug,source_slug,merge_id DESC);
CREATE INDEX node_merges_target_history ON public.node_merges(project_slug,target_slug,id DESC);

-- Project bindings record the human-confirmed native project target of each
-- SpecGraph project. Revoked rows are retained history; at most one binding
-- per project is active at a time.
--

CREATE TABLE public.project_bindings (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    project_slug text NOT NULL REFERENCES public.projects(slug),
    environment_id text NOT NULL CHECK (btrim(environment_id) <> ''),
    native_project_id text NOT NULL CHECK (btrim(native_project_id) <> ''),
    workspace_root text,
    reason text NOT NULL CHECK (char_length(reason) BETWEEN 1 AND 4000),
    actor text NOT NULL CHECK (btrim(actor) <> ''),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone,
    revoke_reason text CHECK (revoke_reason IS NULL OR char_length(revoke_reason) BETWEEN 1 AND 4000),
    revoked_by text CHECK (revoked_by IS NULL OR btrim(revoked_by) <> '')
);

CREATE UNIQUE INDEX project_bindings_active ON public.project_bindings USING btree (project_slug) WHERE (revoked_at IS NULL);
CREATE INDEX project_bindings_history ON public.project_bindings USING btree (project_slug, id DESC);

